-- 전 구간 확인 테스트

@SpringBootTest
@Transactional
class SetupVerifyTest {

    @Autowired MemberRepository memberRepository;
    @PersistenceContext EntityManager em;

    @Test
    void 전_구간() {
        System.out.println("1) 빈    : " +
                memberRepository.getClass().getSimpleName());
        Member saved = memberRepository.save(new Member("확인"));
        System.out.println("2) id    : " + saved.getId());
        em.flush();
        em.clear();
        Member found = memberRepository.findById(saved.getId())
                                       .orElseThrow();
        System.out.println("3) 조회  : " + found.getUsername());
        System.out.println("4) 개수  : " + memberRepository.count());
    }
}

